head.script:
scwin.check1 = function() {
    var ret1 = "aaaa<br>bbbb";
    var ret2 = "aaaabbbb";
    var target = WebSquare.wUnit.getDomById($p.id+'generator1_0_tt').textContent;
    return target === ret1 || target === ret2;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("assert", "scwin.check1()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    generator1.insertChild();
    generator1.insertChild();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 26-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
